#!/usr/bin/env node
/**
 * Regenerate the iamcc-ui skill assets from the UI playground.
 *
 *   node .claude/skills/iamcc-ui/scripts/sync_from_playground.mjs [path/to/playground.html]
 *
 * Default source: docs/iamcc-ui-playground-standalone.html (repo root = 4 levels up).
 * Writes into ../assets/: tokens.css, tokens.json, components.css, fonts.css, icons.svg, eu-emblem.svg.
 * The "PDF spec + corrections" preset (SPEC) is the one exported, as the IAM-IQ UI standard requires.
 * Run it whenever the playground changes; never hand-edit the generated files.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repo = resolve(here, '../../../..');
const src = resolve(process.argv[2] ?? join(repo, 'docs/iamcc-ui-playground-standalone.html'));
const out = resolve(here, '../assets');
mkdirSync(out, { recursive: true });

const html = readFileSync(src, 'utf8');
const BANNER = `/* GENERATED by .claude/skills/iamcc-ui/scripts/sync_from_playground.mjs from ${src.replace(repo + '/', '')}. Do not edit. */\n`;

function must(m, what) {
  if (!m) throw new Error(`could not find ${what} in ${src}`);
  return m;
}

// ---------------------------------------------------------------- tokens
const script = must(html.match(/<script>([\s\S]*?)<\/script>\s*<\/body>/), 'main <script>')[1];
const tokenCode = script.slice(0, must(script.indexOf('/* ============================ CONTROLS'), 'CONTROLS marker'));
const varLine = must(script.match(/const VAR = \{[^\n]*\};/), 'VAR map')[0];
const remLine = must(script.match(/const REMVAR = \{[^\n]*\};/), 'REMVAR map')[0];
const exportFn = must(script.match(/function renderExport\(\)\{[\s\S]*?\n\}/), 'renderExport()')[0]
  .replace("document.getElementById('exportCss').value=", 'return ');

const { SPEC, css } = new Function(`${tokenCode}\n${varLine}\n${remLine}\n${exportFn}\nT = {...SPEC};\nreturn { SPEC, css: renderExport() };`)();
writeFileSync(join(out, 'tokens.css'), BANNER + css + '\n');
writeFileSync(join(out, 'tokens.json'), JSON.stringify(SPEC, null, 2) + '\n');

// ---------------------------------------------------------------- fonts (inlined Google Sans, SIL OFL)
const styles = [...html.matchAll(/<style>([\s\S]*?)<\/style>/g)].map(m => m[1]);
const fontBlock = must(styles.find(s => s.includes('@font-face')), '@font-face block');
writeFileSync(join(out, 'fonts.css'), BANNER + fontBlock.trim() + '\n');

// ---------------------------------------------------------------- components
const previewCss = must(styles.find(s => s.includes('PREVIEW')), 'preview <style>');
const body = previewCss.slice(previewCss.indexOf('#pv{'));

// Split into top-level rules, keeping @-blocks (container queries, keyframes) whole.
function rules(text) {
  const list = []; let depth = 0, start = 0;
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}' && --depth === 0) { list.push(text.slice(start, i + 1).trim()); start = i + 1; }
  }
  return list.filter(Boolean);
}

// Playground-only demos and preview toggles that a real page never needs.
const DEMO = /#pv \.(swatches|swatch|spacebar|rad|elev|colgrid|matrix|series-sw|ramp)\b/;
const STATE_DEMO = /#pv\.(force-focus|alert-status)|\.is-(hover|focus|disabled|error)\b/;

function cleanSelectors(sel) {
  const kept = sel.split(',').map(s => s.trim()).filter(s => s && !STATE_DEMO.test(s) && !DEMO.test(s));
  return kept.join(',');
}

function cleanRule(rule) {
  if (rule.startsWith('/*')) {                       // a comment glued to the next rule
    const end = rule.indexOf('*/') + 2;
    const rest = cleanRule(rule.slice(end).trim());
    return rest ? rule.slice(0, end) + '\n' + rest : '';
  }
  if (rule.startsWith('@keyframes')) return rule;
  if (rule.startsWith('@container')) {
    const open = rule.indexOf('{');
    const inner = rules(rule.slice(open + 1, -1)).map(cleanRule).filter(Boolean);
    return inner.length ? `${rule.slice(0, open + 1)}${inner.join('')}}` : '';
  }
  const open = rule.indexOf('{');
  const sel = cleanSelectors(rule.slice(0, open));
  return sel ? `${sel}{${rule.slice(open + 1)}` : '';
}

let comp = rules(body).map(cleanRule).filter(Boolean).join('\n')
  .replaceAll('@container pv', '@container iq')
  .replaceAll('#pv', '.iq')
  .replace('.iq{\n  container-type:inline-size;container-name:pv;',
    '.iq{\n  container-type:inline-size;container-name:iq;\n  /* set by the playground at runtime; fixed here */\n  --shadow:1;--ring-coral:var(--c-coral);--ring-slate:var(--c-slate);');
if (!comp.includes('container-name:iq')) throw new Error('root .iq block not rewritten; check the playground #pv block');

const prelude = `/* Needs tokens.css first. Wrap the page in <div class="iq">…</div>: it is the container for the
   12/8/4-column breakpoints (75rem / 48rem), so layouts follow the content width, not the window. */
.iq,.iq *,.iq *::before,.iq *::after{box-sizing:border-box}
html{font-size:100%}
body{margin:0;background:var(--c-page)}
.iq{min-height:100vh;display:flex;flex-direction:column}
.iq>main{flex:1}
`;
writeFileSync(join(out, 'components.css'), BANNER + prelude + comp + '\n');

// ---------------------------------------------------------------- icons + EU emblem
// The playground's logo symbols leave <g> groups open; the HTML parser closes them at </symbol>, XML does not.
const sprite = must(html.match(/<svg width="0" height="0"[^>]*>([\s\S]*?)<\/svg>\s*<div class="app">/), 'icon sprite')[1]
  .replace(/<symbol\b[\s\S]*?<\/symbol>/g, sym => {
    const open = (sym.match(/<g[\s>]/g) || []).length - (sym.match(/<\/g>/g) || []).length;
    return open > 0 ? sym.replace(/<\/symbol>$/, '</g>'.repeat(open) + '</symbol>') : sym;
  });
writeFileSync(join(out, 'icons.svg'),
  // No "--" inside the XML comment: it makes the file invalid and every icon silently disappears.
  `<svg xmlns="http://www.w3.org/2000/svg">\n<!-- GENERATED from the playground sprite. Use: <svg class="ico"><use href="icons.svg#i-search"/></svg>.\n     The logo and mark take their colours from the logo-ink and logo-dot custom properties set on .iq. -->\n${sprite.trim()}\n</svg>\n`);

const eu = must(html.match(/<img src="data:image\/svg\+xml;base64,([A-Za-z0-9+/=]+)" alt="Funded by the European Union">/), 'EU emblem')[1];
writeFileSync(join(out, 'eu-emblem.svg'), Buffer.from(eu, 'base64'));

const stat = f => `${f} (${readFileSync(join(out, f)).length.toLocaleString()} B)`;
console.log('wrote', ['tokens.css', 'tokens.json', 'fonts.css', 'components.css', 'icons.svg', 'eu-emblem.svg'].map(stat).join(', '));
